int main(int argc,char**argv){try{if(argc<5)throw std::runtime_error("mode input output/ROI args");std::string mode=argv[1];Mesh m;if(mode=="rays"){m.load(argv[2]);rays(m,argv[3],argv[4]);}else if(mode=="audit"){if(argc!=7)throw std::runtime_error("audit SOURCE RES ROI OUT MULT");int r=std::stoi(argv[3]);if(r!=512&&r!=1024&&r!=1536&&r!=2048)throw std::runtime_error("resolution prohibited");m.load(argv[2],r);std::ifstream f(argv[4]);int n;f>>n;std::vector<Box>boxes(n);for(auto&b:boxes){for(auto&x:b.lo)f>>x;for(auto&x:b.hi)f>>x;}if(!f)throw std::runtime_error("ROI file");audit(m,r,boxes,argv[5],std::stod(argv[6]));}else throw std::runtime_error("mode");return 0;}catch(std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
